import os, tempfile, threading
from carbon_market import audit

def ev(i):
    return {"op": "copy", "target": f"t-{i}.history", "key": "batch-key",
            "changed": True, "error": None, "stage": None}

d = tempfile.mkdtemp()
j = os.path.join(d, "audit.json")
errors = []
def worker(i):
    try:
        audit.record(j, f"k-{i:03d}", ev(i))
    except Exception as e:
        errors.append(e)
threads = [threading.Thread(target=worker, args=(i,)) for i in range(24)]
for t in threads: t.start()
for t in threads: t.join()
assert not errors, errors
r = audit.verify(j)
print("concurrent:", r["valid"], r["count"])
assert r["valid"] and r["count"] == 24
EOF
